-- snippet(正しい書き方) 追加 (Terraform Associate 31問) 2026-07-16
-- 既存キーは変更せず snippet のみ加算マージ。概念問題19問には意図的に付けない。
BEGIN;

UPDATE public.questions q
SET explanation_data = q.explanation_data || jsonb_build_object('snippet', v.value)
FROM jsonb_each_text('{"terraform-associate-q4": "terraform {\n  required_providers {\n    aws = {\n      source  = \"hashicorp/aws\"\n      version = \"~> 5.0\"\n    }\n  }\n}", "terraform-associate-q8": "provider \"aws\" {\n  region = \"us-east-1\"\n}\n\n# 名札(alias)を付けた2つ目の窓口\nprovider \"aws\" {\n  alias  = \"tokyo\"\n  region = \"ap-northeast-1\"\n}\n\nresource \"aws_s3_bucket\" \"my_bucket\" {\n  provider = aws.tokyo\n  bucket   = \"my-example-bucket\"\n}", "terraform-associate-q10": "# 構成(.tf)を書いたあとの基本の並び\nterraform init\nterraform plan\nterraform apply", "terraform-associate-q14": "# 現行の置換方法(terraform taint は非推奨)\nterraform apply -replace=aws_instance.web", "terraform-associate-q16": "# 計画を保存し、その内容どおりに適用する\nterraform plan -out=tfplan\nterraform apply tfplan", "terraform-associate-q17": "# 作成・管理する\nresource \"aws_s3_bucket\" \"my_bucket\" {\n  bucket = \"my-example-bucket\"\n}\n\n# 既存のものを参照する(作成しない)\ndata \"aws_s3_bucket\" \"existing\" {\n  bucket = \"existing-example-bucket\"\n}", "terraform-associate-q18": "# ○ ハイフンを含むキーは [\"...\"] で参照する\nlocals {\n  east_cidr = var.vpc_cidrs[\"us-east-1\"]\n}\n\n# ✗ ドット記法はハイフン入りキーには使えない\n# var.vpc_cidrs.us-east-1", "terraform-associate-q19": "variable \"server\" {\n  type = object({\n    name = string\n    port = number\n  })\n}", "terraform-associate-q20": "# map をそのまま渡せる\nresource \"aws_instance\" \"web\" {\n  for_each      = { a = \"t3.micro\", b = \"t3.small\" }\n  instance_type = each.value\n}\n\n# list は toset() で set にしてから渡す\nresource \"aws_iam_user\" \"example\" {\n  for_each = toset(var.names)\n  name     = each.key\n}", "terraform-associate-q21": "# ○ キーで管理されるので、途中を消しても他がずれない\nresource \"aws_instance\" \"web\" {\n  for_each      = toset(var.names)\n  ami           = var.ami_id\n  instance_type = \"t3.micro\"\n  tags          = { Name = each.key }\n}\n\n# ✗ count は番号管理。途中を消すと後続のindexがずれて再作成される\n# resource \"aws_instance\" \"web\" {\n#   count = length(var.names)\n#   tags  = { Name = var.names[count.index] }\n# }", "terraform-associate-q22": "resource \"aws_security_group\" \"example\" {\n  name = \"example\"\n\n  dynamic \"ingress\" {\n    for_each = var.ports\n    content {\n      from_port = ingress.value\n      to_port   = ingress.value\n      protocol  = \"tcp\"\n    }\n  }\n}", "terraform-associate-q23": "variable \"port\" {\n  type = number\n\n  validation {\n    condition     = var.port >= 1 && var.port <= 65535\n    error_message = \"port は 1〜65535 で指定してください。\"\n  }\n}", "terraform-associate-q24": "resource \"aws_instance\" \"example\" {\n  ami           = data.aws_ami.example.id\n  instance_type = \"t3.micro\"\n\n  lifecycle {\n    # 適用「前」に満たすべき前提条件\n    precondition {\n      condition     = data.aws_ami.example.architecture == \"x86_64\"\n      error_message = \"AMI は x86_64 である必要があります。\"\n    }\n\n    # 適用「後」に満たすべき結果条件(self で自身の属性を参照)\n    postcondition {\n      condition     = self.public_dns != \"\"\n      error_message = \"パブリック DNS が割り当てられていません。\"\n    }\n  }\n}", "terraform-associate-q25": "check \"api_health\" {\n  data \"http\" \"example\" {\n    url = \"https://example.com/health\"\n  }\n\n  # 失敗しても警告どまりで apply は止まらない\n  assert {\n    condition     = data.http.example.status_code == 200\n    error_message = \"health エンドポイントが 200 を返していません。\"\n  }\n}", "terraform-associate-q27": "variable \"db_password\" {\n  type      = string\n  sensitive = true  # 画面やログでは隠れるが、state には平文で保存される\n}", "terraform-associate-q28": "resource \"aws_s3_bucket\" \"example\" {\n  bucket = \"my-bucket\"\n}\n\nresource \"aws_instance\" \"app\" {\n  ami           = \"ami-0123456789abcdef0\"\n  instance_type = \"t3.micro\"\n\n  # 参照は無いが、バケットを先に作らせる\n  depends_on = [aws_s3_bucket.example]\n}", "terraform-associate-q29": "# ○ レジストリ由来なら version が使える\nmodule \"vpc\" {\n  source  = \"terraform-aws-modules/vpc/aws\"\n  version = \"~> 5.0\"\n}\n\n# ✗ Git は version 不可。source 側で ref= を使う\nmodule \"vpc_git\" {\n  source = \"git::https://example.com/vpc.git?ref=v1.2.0\"\n}", "terraform-associate-q30": "module \"vpc\" {\n  source     = \"./modules/vpc\"\n  cidr_block = \"10.0.0.0/16\"  # 入力: 子の input variable へ渡す\n}\n\noutput \"vpc_id\" {\n  value = module.vpc.vpc_id  # 出力: 子の output value を受け取る\n}", "terraform-associate-q32": "module \"vpc\" {\n  # namespace / name / provider の3段\n  source  = \"terraform-aws-modules/vpc/aws\"\n  version = \"~> 5.0\"\n}", "terraform-associate-q33": "module \"vpc\" {\n  source  = \"terraform-aws-modules/vpc/aws\"\n  version = \"~> 3.1\"  # 3.1 以上 4.0 未満(3.x 系のみ許可)\n}", "terraform-associate-q34": "terraform {\n  backend \"s3\" {\n    bucket = \"my-tfstate\"\n    key    = \"prod/terraform.tfstate\"\n    region = \"us-east-1\"\n  }\n}", "terraform-associate-q37": "# 構成と実インフラのズレ(ドリフト)を表示する\nterraform plan\n\n# stateの実態同期だけを確認したい場合\nterraform plan -refresh-only", "terraform-associate-q38": "# 実リソースは再作成せず、state上のアドレスだけ移す\nmoved {\n  from = aws_instance.old\n  to   = aws_instance.new\n}", "terraform-associate-q39": "# 実インフラは残したまま、Terraform管理からだけ外す\nremoved {\n  from = aws_instance.example\n\n  lifecycle {\n    destroy = false\n  }\n}", "terraform-associate-q40": "# 実インフラは変更せず、stateだけを実態に合わせる\nterraform plan -refresh-only\nterraform apply -refresh-only", "terraform-associate-q41": "# to = 取り込み先アドレス, id = 実リソースのID\nimport {\n  to = aws_instance.example\n  id = \"i-0123456789abcdef0\"\n}", "terraform-associate-q42": "# importブロックを書いた上で実行すると、対応するHCLが生成される\nterraform plan -generate-config-out=generated.tf", "terraform-associate-q43": "# state内のリソースアドレスを一覧表示\nterraform state list", "terraform-associate-q44": "# アドレスを指定して単一リソースの属性を表示\nterraform state show aws_instance.example", "terraform-associate-q45": "# TRACE / DEBUG / INFO / WARN / ERROR が指定できる\nexport TF_LOG=DEBUG\nterraform apply", "terraform-associate-q46": "# TF_LOG とセットで使い、ログをファイルに出力する\nexport TF_LOG=DEBUG\nexport TF_LOG_PATH=./terraform.log\nterraform apply"}'::jsonb) AS v(key, value)
WHERE q.source_ref = v.key
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'terraform-associate')
  AND q.explanation_data IS NOT NULL;

COMMIT;
